<?php declare(strict_types=1);namespace NpmGateway\Console;use NpmGateway\Services\MarketingFlyerNotificationWorker;
final class MarketingFlyerNotificationWorkerCommand{public function __construct(private readonly MarketingFlyerNotificationWorker$worker){}public function run(array$args):array{if(count($args)>1)return['exit_code'=>2,'stdout'=>'','stderr'=>"Usage: marketing-flyer-notifications:work [batch-size]\n"];$limit=isset($args[0])?(int)$args[0]:10;if($limit<1||$limit>100)return['exit_code'=>2,'stdout'=>'','stderr'=>"Batch size must be between 1 and 100.\n"];$started=hrtime(true);$r=$this->worker->run($limit);$ms=(int)((hrtime(true)-$started)/1_000_000);return['exit_code'=>$r['exit'],'stdout'=>"Marketing Flyer notification worker: {$r['processed']} processed, {$r['delivered']} delivered, {$r['retry']} retrying, {$r['failed']} failed, {$ms} ms.\n",'stderr'=>''];}}
